import{_ as d,l as t,o as n,c as r,v as e,p as i,x as o,d as s,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"Lyndon 分解","description":"","frontmatter":{"title":"Lyndon 分解","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lyndon-duval.md","filePath":"cs/lyndon-duval.md","lastUpdated":1789023840000}'),u={name:"cs/lyndon-duval.md"};function c(_,a,y,L,m,f){const l=t("Mermaid");return n(),r("div",null,[a[1]||(a[1]=e('<h1 id="lyndon-分解" tabindex="-1">Lyndon 分解 <a class="header-anchor" href="#lyndon-分解" aria-label="Permalink to &quot;Lyndon 分解&quot;">​</a></h1><div class="epigraph"><p>Lyndon 字严格小于其所有真后缀；每个串唯一分解成非增的 Lyndon 字串联，Duval 线性算出。</p><footer>—— 据 Chen, Fox and Lyndon, 1958；Duval, Factorizing Words over an Ordered Alphabet, 1983 整理</footer></div><p>上一课<a href="/cs/suffix-array-applications">后缀数组的应用</a>能取最小后缀。Lyndon 字：本原且字典序最小的旋转（等价：小于所有真后缀）。缺口是 Duval 分解：把 \\(s\\) 写成 \\(\\ell_1\\ge \\ell_2\\ge\\cdots\\) 的 Lyndon 串。与最小表示：一个 Lyndon 的最小表示是自身。不重写 SA。后课正则回溯。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Duval：三个指针扫，比较当前候选 Lyndon。线性。应用：最小表示（最长 Lyndon 前缀相关）、最长 Lyndon 前缀、与 KMP 的 border 关系点名。</p><p>缺口是分解唯一性（Chen–Fox–Lyndon 定理），不是 SA 排序。</p><h3 id="不是随便的因子分解" tabindex="-1">不是随便的因子分解 <a class="header-anchor" href="#不是随便的因子分解" aria-label="Permalink to &quot;不是随便的因子分解&quot;">​</a></h3><p>Lyndon 分解对给定字母序唯一。换序则变。不要与质因子分解混名。</p><p><span class="marginnote">CFL 定理 1958。Duval 1983 线性算法。后课正则是语言匹配，不是字的 Lyndon。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Duval 实现（标准三指针）。输出切点。最小旋转：对 \\(s+s\\) 做 Lyndon 或用前课双指针。</p>',11)),(n(),i(h,null,{default:o(()=>[p(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E4%B8%B2%20s%22%5D%20--%3E%20DUV%5B%22Duval%20%E4%B8%89%E6%8C%87%E9%92%88%22%5D%0A%20%20DUV%20--%3E%20LYN%5B%22%E9%9D%9E%E5%A2%9E%20Lyndon%20%E4%B8%B2%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>字母必须全序。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Lyndon 的真后缀都更大，故拼接非增时字典序结构良。Duval 类似最小表示的跳跃。与 SA：最长 Lyndon 后缀等可用 SA，但分解本身线性不必 SA。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写项链多项式。不写 bi-infinite。后课默认：Lyndon 分解线性 Duval。下一课正则匹配与回溯爆炸。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Lyndon 字小于真后缀；分解唯一非增。</li><li>Duval \\(O(n)\\)。</li><li>与最小表示、SA 接口，本课要分解。</li><li>出处：Chen, Fox and Lyndon, 1958；Duval, 1983。</li></ul>',7))])}const b=d(u,[["render",c]]);export{D as __pageData,b as default};
